import sqlite3
from dataclasses import dataclass
from datetime import date
from typing import Optional

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("hr-payroll")

DB_PATH = "hr.db"
ALLOWED_ROLES = {"viewer", "payroll_clerk", "payroll_approver", "hr_admin"}


@dataclass
class RoleChangeResult:
    employee_id: str
    old_role: Optional[str]
    new_role: str
    expires_on: Optional[str]
    success: bool
    message: str


@mcp.tool()
def update_employee_payroll_access_role(
    employee_id: str,
    new_role: str,
    granted_by: str,
    expires_on: Optional[str] = None,
) -> RoleChangeResult:
    if new_role not in ALLOWED_ROLES:
        return RoleChangeResult(employee_id, None, new_role, expires_on, False, "Unknown role")

    if expires_on:
        try:
            if date.fromisoformat(expires_on) <= date.today():
                return RoleChangeResult(employee_id, None, new_role, expires_on, False, "Expiry must be in the future")
        except ValueError:
            return RoleChangeResult(employee_id, None, new_role, expires_on, False, "Invalid expiry date")

    conn = sqlite3.connect(DB_PATH)
    try:
        cur = conn.cursor()
        cur.execute("SELECT role FROM payroll_access WHERE employee_id = ?", (employee_id,))
        row = cur.fetchone()
        if row is None:
            return RoleChangeResult(employee_id, None, new_role, expires_on, False, "Employee has no access record")
        old_role = row[0]
        cur.execute(
            "UPDATE payroll_access SET role = ?, expires_on = ?, granted_by = ? WHERE employee_id = ?",
            (new_role, expires_on, granted_by, employee_id),
        )
        cur.execute(
            "INSERT INTO access_audit (employee_id, old_role, new_role, granted_by, changed_at) VALUES (?, ?, ?, ?, ?)",
            (employee_id, old_role, new_role, granted_by, date.today().isoformat()),
        )
        conn.commit()
    finally:
        conn.close()

    return RoleChangeResult(employee_id, old_role, new_role, expires_on, True, "Role updated")
